// GrantsSeqCase is how a console orders reads on one connection: it keeps
// the read with the highest seq it got on that connection, the reply to
// its grants.get included, and drops an event whose seq is not higher. seq
// is per Den process: after a redial a console forgets what it kept and
// asks again.
type GrantsSeqCase struct {
	Name string
	// Kept is the seq the console holds; Event is a grants event's.
	Kept, Event uint64
	// Take: the console replaces what it holds with the event's read.
	Take bool
}

// GrantsSeqCases is the table both sides are pinned to.
var GrantsSeqCases = []GrantsSeqCase{
	{Name: "a later change", Kept: 7, Event: 8, Take: true},
	{Name: "a change pushed before the reply it raced", Kept: 7, Event: 7},
	{Name: "an older read", Kept: 7, Event: 6},
}
